-- ① 自分のルーム（1本）。UNIQUE は (talk_room_id, user_id)
--   の並びなので、user_id だけでは使えず、全部読む
select * from "talk_room_members"
where "user_id" = 23;

-- ② ルーム1つごとに6本（ルーム 7・相手 5 のとき）
select * from "talk_rooms" where "id" = 7 limit 1;
-- これは UNIQUE (talk_room_id, user_id) が効く
select * from "talk_room_members"
where "talk_room_id" = 7 and "user_id" != 23 limit 1;
select * from "profiles" where "user_id" = 5 limit 1;
select "public_id" from "users" where "id" = 5 limit 1;
-- 外部キーはあるがインデックスがないので、
-- messages を全部読んで並べ替える
select * from "messages"
where "talk_room_id" = 7
order by "created_at" desc limit 1;
-- これも messages を全部読む
select count(*) as "aggregate" from "messages"
where "talk_room_id" = 7
  and "sender_id" != 23
  and "created_at" > '2026-11-13 09:00:00';
